
.workspace-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.summary-grid,
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
}

.summary-card,
.entity-card {
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
}

.summary-card {
  padding: 14px;
}

.summary-card span,
.toolbar-copy,
.card-footer,
.slot-copy {
  color: #8b95b4;
  font-size: 12px;
}

.summary-card strong {
  display: block;
  margin-top: 8px;
  color: #eef2ff;
}

.shop-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
  flex-wrap: wrap;
}

.refresh-button {
  border: 1px solid rgba(0, 229, 255, 0.24);
  border-radius: 8px;
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
  cursor: pointer;
  padding: 10px 14px;
}

.shop-feedback {
  margin: 10px 0 0;
  color: #8b95b4;
  font-size: 12px;
  line-height: 1.6;
}

.tab-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}

.tab-button {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: #c9d1e8;
  cursor: pointer;
  padding: 8px 14px;
}

.tab-button--active {
  border-color: rgba(0, 229, 255, 0.22);
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
}

.entity-card {
  padding: 14px;
  color: #dbe3ff;
  text-align: left;
  cursor: pointer;
}

.entity-card:hover {
  border-color: rgba(0, 229, 255, 0.22);
  background: rgba(0, 229, 255, 0.06);
}

.entity-card--sold-out,
.entity-card--sold-out:hover {
  border-color: rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.015);
}

.entity-card--sold-out {
  opacity: 0.74;
}

.card-header,
.card-footer,
.meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.card-header {
  margin-bottom: 8px;
  align-items: flex-start;
}

.meta-row {
  margin-bottom: 10px;
}

.card-footer {
  margin-top: 12px;
  flex-wrap: wrap;
}

.price-tag,
.category-pill,
.rarity-tag,
.sold-out-tag {
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 11px;
}

.price-tag {
  background: rgba(255, 184, 77, 0.16);
  color: #ffd089;
}

.sold-out-tag {
  background: rgba(255, 107, 129, 0.14);
  color: #ff9aaa;
}

.category-pill {
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
}

.rarity-N { background: rgba(255,255,255,0.08); color: #c9d1e8; }
.rarity-R { background: rgba(0,229,255,0.12); color: #76f4ff; }
.rarity-SR { background: rgba(168,85,247,0.14); color: #d8a0ff; }
.rarity-SSR { background: rgba(255,184,77,0.16); color: #ffd089; }

h4,
p {
  margin: 0;
}

p {
  color: #aeb7d1;
  line-height: 1.6;
}

.slot-copy {
  margin-top: 4px;
}

@media (max-width: 720px) {
  .shop-workspace {
    gap: 12px;
  }

  .shop-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .summary-grid,
  .card-grid {
    grid-template-columns: 1fr;
  }

  .tab-row {
    gap: 8px;
  }

  .tab-button {
    flex: 1 1 calc(50% - 4px);
    min-height: 42px;
    justify-content: center;
  }

  .card-header,
  .meta-row,
  .card-footer {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .summary-grid,
  .card-grid {
    gap: 10px;
  }

  .refresh-button,
  .tab-button {
    width: 100%;
    justify-content: center;
  }

  .entity-card {
    padding: 12px;
  }

  h4,
  p,
  .card-footer,
  .slot-copy {
    overflow-wrap: anywhere;
  }
}
