
.workspace-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.summary-grid,
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
}

.summary-card,
.entity-card {
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
}

.summary-card {
  padding: 14px;
}

.summary-card span,
.meta-line,
.empty-copy,
.toolbar-copy,
.card-footer {
  color: #8b95b4;
  font-size: 12px;
}

.summary-card strong,
h4 {
  color: #eef2ff;
}

.summary-card strong {
  display: block;
  margin-top: 8px;
}

.item-pool-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.create-button {
  width: 40px;
  height: 40px;
  border: 1px solid rgba(0, 229, 255, 0.24);
  border-radius: 8px;
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
  cursor: pointer;
  font-size: 24px;
  line-height: 1;
}

.create-button:hover {
  border-color: rgba(0, 229, 255, 0.42);
  background: rgba(0, 229, 255, 0.14);
}

.tab-row,
.filter-row,
.chip-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.tab-row,
.filter-row {
  margin-bottom: 6px;
}

.tab-button,
.filter-button {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: #c9d1e8;
  cursor: pointer;
  padding: 8px 14px;
}

.tab-button--active,
.filter-button--active {
  border-color: rgba(0, 229, 255, 0.22);
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
}

.entity-card {
  padding: 14px;
  color: #dbe3ff;
  text-align: left;
  cursor: pointer;
}

.entity-card:hover {
  border-color: rgba(0, 229, 255, 0.22);
  background: rgba(0, 229, 255, 0.06);
}

.card-header,
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.card-header {
  margin-bottom: 10px;
}

.card-footer {
  margin-top: 12px;
}

h4,
p {
  margin: 0;
}

p {
  color: #aeb7d1;
  line-height: 1.6;
}

.chip-row {
  margin-bottom: 10px;
}

.category-pill,
.rarity-tag {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  font-size: 11px;
}

.category-pill {
  padding: 4px 8px;
  background: rgba(255, 255, 255, 0.06);
  color: #dbe3ff;
}

.rarity-tag {
  flex: 0 0 auto;
  padding: 4px 8px;
}

.rarity-N { background: rgba(255,255,255,0.08); color: #c9d1e8; }
.rarity-R { background: rgba(0,229,255,0.12); color: #76f4ff; }
.rarity-SR { background: rgba(168,85,247,0.14); color: #d8a0ff; }
.rarity-SSR { background: rgba(255,184,77,0.16); color: #ffd089; }
