
.workspace-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.character-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.character-tabs button,
.sort-select {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  color: #c9d1e8;
  padding: 8px 12px;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
}

.character-tabs button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.character-tabs button.active {
  border-color: rgba(0, 229, 255, 0.28);
  background: rgba(0, 229, 255, 0.12);
  color: #76f4ff;
}

.character-tabs strong {
  color: inherit;
  font-weight: 600;
}

.toolbar-row,
.card-header,
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.toolbar-row {
  flex-wrap: wrap;
  margin-bottom: 12px;
}

.tab-hint,
.meta-line,
.card-footer {
  color: #8b95b4;
  font-size: 12px;
}

.tab-hint {
  margin: 0;
}

.sort-select option {
  background: #0b0f20;
  color: #f7f9ff;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}

.entity-card,
.empty-card {
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
}

.entity-card {
  padding: 14px;
  color: #dbe3ff;
  cursor: pointer;
  text-align: left;
}

.entity-card:hover,
.entity-card--active {
  border-color: rgba(0, 229, 255, 0.22);
  background: rgba(0, 229, 255, 0.06);
}

.card-header {
  margin-bottom: 8px;
}

.card-footer {
  margin-top: 10px;
}

.mini-meter {
  height: 6px;
  margin-top: 12px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
}

.mini-meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #00e5ff, #a855f7);
}

.state-pill {
  flex: 0 0 auto;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(168, 85, 247, 0.14);
  color: #d8a0ff;
  font-size: 11px;
}

.empty-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 22px;
  color: #8b95b4;
  text-align: center;
}

.empty-card strong {
  color: #eef2ff;
}

h4,
p {
  margin: 0;
}

h4 {
  color: #eef2ff;
}

p {
  color: #aeb7d1;
  line-height: 1.6;
}

@media (max-width: 720px) {
  .toolbar-row {
    align-items: flex-start;
    flex-direction: column;
  }
}
