
.workspace-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.summary-grid,
.milestone-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.summary-card,
.milestone-card,
.reward-record-card {
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  padding: 14px;
}

.summary-card span,
.empty-copy {
  color: #8b95b4;
  font-size: 12px;
}

.summary-card strong,
.milestone-card h4 {
  display: block;
  margin-top: 8px;
  color: #eef2ff;
}

.checkin-button {
  margin-top: 14px;
  border: 1px solid rgba(0, 229, 255, 0.24);
  border-radius: 8px;
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
  cursor: pointer;
  padding: 10px 14px;
}

.checkin-button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

.calendar-legend,
.calendar-weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
}

.calendar-legend {
  margin-bottom: 12px;
}

.calendar-month-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  color: #dbe3ff;
}

.calendar-month-title strong {
  color: #eef2ff;
  font-size: 18px;
}

.calendar-month-title span {
  color: #8b95b4;
  font-size: 12px;
}

.legend-chip,
.calendar-weekdays span {
  border-radius: 999px;
  padding: 6px 8px;
  text-align: center;
  font-size: 12px;
}

.legend-chip {
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: #dbe3ff;
  background: rgba(255, 255, 255, 0.04);
}

.legend-chip--signed {
  border-color: rgba(34, 197, 94, 0.22);
  background: rgba(34, 197, 94, 0.12);
}

.legend-chip--today {
  border-color: rgba(0, 229, 255, 0.24);
  background: rgba(0, 229, 255, 0.12);
}

.legend-chip--milestone {
  border-color: rgba(168, 85, 247, 0.24);
  background: rgba(168, 85, 247, 0.12);
}

.calendar-weekdays {
  margin-bottom: 10px;
}

.calendar-weekdays span {
  color: #8b95b4;
  background: rgba(255, 255, 255, 0.02);
}

.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
}

.calendar-cell {
  min-height: 124px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.03);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.calendar-cell strong {
  color: #eef2ff;
  font-size: 14px;
}

.calendar-cell p,
.milestone-card p,
.reward-record-card p {
  margin: 0;
  color: #aeb7d1;
  line-height: 1.5;
  font-size: 12px;
}

.calendar-cell__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.calendar-cell__day {
  color: #dbe3ff;
  font-size: 16px;
  font-weight: 700;
}

.calendar-cell__badge {
  color: #d8b4fe;
  font-size: 14px;
}

.calendar-reward {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.calendar-reward span {
  color: #76f4ff;
  font-size: 12px;
}

.calendar-reward small {
  color: #dbe3ff;
  font-size: 11px;
}

.calendar-cell--empty {
  opacity: 0.25;
  background: rgba(255, 255, 255, 0.015);
}

.calendar-cell--signed {
  border-color: rgba(34, 197, 94, 0.24);
  background: rgba(34, 197, 94, 0.1);
}

.calendar-cell--today {
  border-color: rgba(0, 229, 255, 0.3);
  background: rgba(0, 229, 255, 0.1);
  box-shadow: 0 0 0 1px rgba(0, 229, 255, 0.1) inset;
}

.calendar-cell--future {
  opacity: 0.72;
}

.calendar-cell--milestone {
  box-shadow: 0 0 0 1px rgba(168, 85, 247, 0.14) inset;
}

.reward-record-list {
  display: grid;
  gap: 10px;
}

.reward-record-card {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.reward-record-card strong,
.reward-record-card span {
  display: block;
}

.reward-record-card strong {
  color: #eef2ff;
}

.reward-record-card span {
  margin-top: 4px;
  color: #8b95b4;
  font-size: 12px;
}

.reward-record-card p {
  max-width: 360px;
  text-align: right;
}

.milestone-card--active {
  border-color: rgba(168, 85, 247, 0.24);
  background: rgba(168, 85, 247, 0.08);
}

@media (max-width: 900px) {
  .calendar-legend,
  .calendar-weekdays,
  .calendar-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .calendar-legend,
  .calendar-weekdays,
  .calendar-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .calendar-month-title,
  .reward-record-card {
    flex-direction: column;
  }

  .reward-record-card p {
    text-align: left;
  }
}
