
.workspace-stack,
.settings-stack,
.summary-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.summary-overview {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px;
  border: 1px solid rgba(0, 229, 255, 0.14);
  border-radius: 10px;
  background:
    radial-gradient(circle at top right, rgba(0, 229, 255, 0.1), transparent 42%),
    rgba(255, 255, 255, 0.025);
}

.overview-kicker,
.field small,
.switch-row small,
.empty-state p,
.feedback {
  color: #8b95b4;
  font-size: 12px;
  line-height: 1.55;
}

.overview-kicker {
  display: block;
  color: #76f4ff;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h3,
p {
  margin: 0;
}

h3 {
  margin-top: 5px;
  color: #eef2ff;
  font-size: 18px;
}

.summary-overview p {
  max-width: 540px;
  margin-top: 8px;
  color: #aeb7d1;
  font-size: 13px;
  line-height: 1.6;
}

.overview-stats {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.overview-stats span,
.floor-label,
.current-label {
  padding: 6px 10px;
  border: 1px solid rgba(0, 229, 255, 0.18);
  border-radius: 999px;
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
  font-size: 11px;
  white-space: nowrap;
}

.overview-stats strong {
  color: #eef2ff;
}

.status-pill--muted {
  border-color: rgba(255, 255, 255, 0.08) !important;
  background: rgba(255, 255, 255, 0.03) !important;
  color: #8b95b4 !important;
}

.tab-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.tab-button,
.action-button {
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  color: #c9d1e8;
  cursor: pointer;
  font: inherit;
}

.tab-button {
  padding: 9px 14px;
}

.tab-button--active {
  border-color: rgba(0, 229, 255, 0.34);
  background: rgba(0, 229, 255, 0.1);
  color: #76f4ff;
}

.summary-card {
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.025);
}

.summary-card header,
.action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.current-label {
  border-color: rgba(168, 85, 247, 0.3);
  background: rgba(168, 85, 247, 0.12);
  color: #d8b4fe;
}

.summary-card p {
  margin-top: 10px;
  color: #dbe3ff;
  line-height: 1.75;
  white-space: pre-wrap;
}

.empty-state {
  padding: 22px;
  border: 1px dashed rgba(118, 244, 255, 0.18);
  border-radius: 8px;
  text-align: center;
}

.empty-state strong {
  color: #dbe3ff;
}

.empty-state p {
  margin-top: 8px;
}

.switch-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.025);
  cursor: pointer;
}

.switch-row input {
  width: 18px;
  height: 18px;
  margin: 2px 0 0;
  accent-color: #00e5ff;
}

.switch-row strong,
.switch-row small {
  display: block;
}

.switch-row strong,
.field > span {
  color: #eef2ff;
  font-size: 13px;
}

.switch-row small {
  margin-top: 5px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.field--full {
  width: 100%;
}

.field input,
.field textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid rgba(118, 244, 255, 0.22);
  border-radius: 8px;
  background: rgba(11, 15, 32, 0.94);
  color: #f7f9ff;
  padding: 10px 12px;
  font: inherit;
}

.field textarea {
  min-height: 118px;
  resize: vertical;
}

.field input:focus,
.field textarea:focus {
  outline: none;
  border-color: rgba(118, 244, 255, 0.72);
  box-shadow: 0 0 0 2px rgba(0, 229, 255, 0.1);
}

.action-row {
  justify-content: flex-start;
  flex-wrap: wrap;
}

.action-button {
  padding: 10px 14px;
}

.action-button:hover {
  border-color: rgba(0, 229, 255, 0.3);
  background: rgba(0, 229, 255, 0.08);
}

.action-button--primary {
  border-color: rgba(0, 229, 255, 0.34);
  background: rgba(0, 229, 255, 0.13);
  color: #76f4ff;
}

.feedback {
  margin-left: 4px;
}

@media (max-width: 720px) {
  .summary-overview,
  .overview-stats {
    flex-direction: column;
    align-items: flex-start;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }
}
