
:global(html),
:global(body),
:global(#app) {
  margin: 0;
  width: 100%;
  max-width: 100%;
}

:global(body.neon-career-fullscreen),
:global(body.neon-career-fullscreen #app) {
  height: 100%;
  overflow: hidden;
}

:global(body) {
  overflow-x: hidden;
}

.shell {
  display: flex;
  flex-direction: column;
  gap: 18px;
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  padding: clamp(12px, 2.2vw, 20px);
  box-sizing: border-box;
  color: #e8e4f0;
  background: #06060e;
  font-family: 'Noto Sans SC', 'Microsoft YaHei', sans-serif;
}

.shell--embedded {
  max-width: 100%;
  gap: 14px;
  padding: 12px 10px 16px;
}

.shell--start {
  gap: 0;
  padding: 0;
}

.shell--fullscreen {
  height: 100vh;
  max-height: 100vh;
  overflow: hidden;
}

.shell--fullscreen .topbar,
.shell--fullscreen .input-panel {
  flex: 0 0 auto;
}

.shell--fullscreen .story-layout {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.shell--fullscreen .story-main {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.shell--fullscreen .narrative-panel {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.shell--fullscreen .narrative-scroll-area {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  padding-right: 8px;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(0, 229, 255, 0.42) transparent;
}

.shell--fullscreen .narrative-scroll-area::-webkit-scrollbar {
  width: 6px;
}

.shell--fullscreen .narrative-scroll-area::-webkit-scrollbar-track {
  background: transparent;
}

.shell--fullscreen .narrative-scroll-area::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(0, 229, 255, 0.28);
}

.topbar,
.panel {
  border: 1px solid #1e1e3a;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(17, 17, 34, 0.96) 0%, rgba(12, 12, 24, 0.96) 100%);
  box-shadow: inset 0 1px 0 rgba(0, 229, 255, 0.06);
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: clamp(14px, 2vw, 18px) clamp(16px, 2.2vw, 22px);
}

.topbar-identity {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 6px;
  color: #00e5ff;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1,
h2,
p,
ul,
dl {
  margin: 0;
}

h1 {
  font-size: clamp(20px, 3vw, 24px);
  font-weight: 700;
}

h2 {
  font-size: 14px;
  color: #00e5ff;
}

.status-cluster {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

.chip {
  max-width: 100%;
  padding: 6px 10px;
  border-radius: 6px;
  border: 1px solid rgba(0, 229, 255, 0.2);
  background: rgba(0, 229, 255, 0.08);
  color: #00e5ff;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.story-layout {
  display: block;
  min-height: 0;
}

.story-layout--embedded {
  display: block;
}

.story-main {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
  min-height: 0;
}

.panel {
  min-width: 0;
  padding: clamp(14px, 1.8vw, 18px) clamp(16px, 2vw, 20px);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.compact-header {
  margin-bottom: 14px;
}

.narrative-panel {
  padding: clamp(16px, 2vw, 22px);
  background:
    radial-gradient(circle at 12% 0%, rgba(168, 85, 247, 0.08), transparent 36%),
    linear-gradient(180deg, rgba(14, 14, 30, 0.97) 0%, rgba(8, 8, 18, 0.97) 100%);
}

.input-panel {
  border-color: rgba(0, 229, 255, 0.16);
  padding-block: 12px;
}

.detail-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.detail-summary,
.detail-note {
  color: #dbe3ff;
  line-height: 1.75;
}

.detail-note--system {
  border: 1px solid rgba(168, 85, 247, 0.16);
  border-radius: 8px;
  background: rgba(168, 85, 247, 0.08);
  padding: 10px 12px;
  color: #d8a0ff;
}

.detail-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.detail-chip {
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
  font-size: 12px;
}

.detail-chip--button {
  border: 1px solid rgba(255, 255, 255, 0.08);
  cursor: pointer;
}

.detail-chip--active {
  border-color: rgba(0, 229, 255, 0.24);
  background: rgba(0, 229, 255, 0.12);
}

.item-pool-editor {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 14px;
  border: 1px solid rgba(118, 244, 255, 0.12);
  border-radius: 8px;
  background: rgba(6, 8, 18, 0.78);
}

.editor-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.export-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.editor-grid label,
.export-grid label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: #c9d1e8;
  font-size: 12px;
}

.editor-grid__full {
  grid-column: 1 / -1;
}

.editor-grid input,
.editor-grid select,
.editor-grid textarea,
.export-grid textarea {
  border: 1px solid rgba(118, 244, 255, 0.24);
  border-radius: 8px;
  background: rgba(11, 15, 32, 0.94);
  color: #f7f9ff;
  padding: 10px 12px;
  font: inherit;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.editor-grid input:focus,
.editor-grid select:focus,
.editor-grid textarea:focus,
.export-grid textarea:focus {
  outline: none;
  border-color: rgba(118, 244, 255, 0.72);
  background: rgba(13, 20, 42, 0.98);
  box-shadow: 0 0 0 2px rgba(0, 229, 255, 0.12);
}

.editor-grid input::placeholder,
.editor-grid textarea::placeholder,
.export-grid textarea::placeholder {
  color: #7f8aa8;
}

.editor-grid select option {
  background: #0b0f20;
  color: #f7f9ff;
}

.detail-field-list {
  display: grid;
  gap: 12px;
}

.detail-field-list div {
  display: grid;
  gap: 4px;
}

.detail-field-list dt {
  color: #8b95b4;
  font-size: 12px;
}

.detail-field-list dd {
  color: #eef2ff;
  overflow-wrap: anywhere;
}

.detail-reward-list {
  display: grid;
  gap: 10px;
}

.detail-reward-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
}

@media (max-width: 720px) {
  .topbar,
  .panel-header,
  .detail-reward-item {
    flex-direction: column;
    align-items: flex-start;
  }

  .topbar {
    gap: 10px;
    padding-right: 72px;
  }

  .topbar-identity {
    display: none;
  }

  .status-cluster {
    justify-content: flex-start;
    gap: 6px;
  }

  .chip {
    padding: 5px 8px;
    font-size: 11px;
  }

  .input-panel {
    padding: 12px;
  }

  .editor-grid,
  .export-grid {
    grid-template-columns: 1fr;
  }
}
