
.workspace-stack,
.group-stack,
.list-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.summary-card,
.entity-card {
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
}

.summary-card {
  padding: 14px;
}

.summary-card span,
.meta-line,
.card-footer,
.empty-copy,
.reward-stack {
  color: #8b95b4;
  font-size: 12px;
}

.summary-card strong,
.state-pill,
h4 {
  color: #eef2ff;
}

.summary-card strong {
  display: block;
  margin-top: 8px;
}

.tab-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}

.tab-button {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: #c9d1e8;
  cursor: pointer;
  padding: 8px 14px;
}

.tab-button--active {
  border-color: rgba(0, 229, 255, 0.22);
  background: rgba(0, 229, 255, 0.08);
  color: #76f4ff;
}

.list-stack--nested {
  gap: 10px;
}

.entity-card {
  padding: 14px;
  color: #dbe3ff;
  text-align: left;
  cursor: pointer;
}

.entity-card:hover {
  border-color: rgba(0, 229, 255, 0.22);
  background: rgba(0, 229, 255, 0.06);
}

.card-header,
.card-footer {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.card-header {
  margin-bottom: 10px;
}

.card-footer {
  margin-top: 10px;
  flex-wrap: wrap;
}

.reward-stack {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  margin-top: 12px;
}

.state-pill {
  flex: 0 0 auto;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(168, 85, 247, 0.14);
  color: #d8a0ff;
  font-size: 11px;
}

h4,
p {
  margin: 0;
}

p {
  color: #aeb7d1;
  line-height: 1.6;
}

.empty-copy {
  margin: 0;
  padding: 10px 0 2px;
}

@media (max-width: 720px) {
  .quest-workspace {
    gap: 12px;
  }

  .summary-grid {
    grid-template-columns: 1fr;
  }

  .tab-row {
    gap: 8px;
  }

  .tab-button {
    flex: 1 1 calc(50% - 4px);
    min-height: 42px;
    justify-content: center;
  }

  .card-header,
  .card-footer,
  .reward-stack {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .summary-grid {
    gap: 10px;
  }

  .tab-button {
    width: 100%;
    justify-content: center;
  }

  .entity-card {
    padding: 12px;
  }

  h4,
  p,
  .reward-stack,
  .card-footer,
  .state-pill {
    overflow-wrap: anywhere;
  }
}
